script:
(async()=>{
  const camera = document.currentScript.currentDMCamera;
  const { CodeParserModule, CodeParser } = camera.dynamsoftExports;
  const { cvRouter, onDriverLicenseResult } = camera.uiContext;
  const ui = camera.ui;

  const parsedResultView = ui.querySelector(".parsed-result-view");
  const homePage = ui.querySelector(".home-page");
  const startIcon = ui.querySelector(".start-icon");
  const startBtn = ui.querySelector(".start-btn");
  const loading = ui.querySelector(".loading");
  const barcodeText = ui.querySelector(".barcode-text");
  const parsedResultList = ui.querySelector(".parsed-result-list");
  const backToScan = ui.querySelector(".back-to-scan");
  const barcodeScannerView = ui.querySelector(".barcode-scanner-view");
  const uploadImageBtn = ui.querySelector(".upload-image-btn");
  const uploadImageInput = ui.querySelector(".upload-image-input");

  CodeParserModule.loadSpec(["AAMVA_DL_ID", "SOUTH_AFRICA_DL"]);

  let parser;
  let isHandlingResult = false;
  let pInit = (async () => {
    parser = await CodeParser.createInstance();
    await cvRouter.addResultReceiver({
      onDecodedBarcodesReceived: (result) => {
        const barcodeResultItem = result.barcodeResultItems?.[0];
        if (!barcodeResultItem) return;
        cvRouter.stopCapturing();
        showResult(barcodeResultItem);
      }
    });
    await cvRouter.initSettings("./read_dl.json");
  })();

  async function start() {
    await pInit;
    await camera.open();
    await cvRouter.startCapturing("ReadDriversLicense");
    barcodeScannerView.style.display = '';
  }

  async function showResult(barcodeResultItem) {
    if (isHandlingResult) return;
    isHandlingResult = true;

    camera.clearAllInnerDrawingItems();

    let processedResult;
    try {
      const parsedResult = await parser.parse(barcodeResultItem.bytes);
      processedResult = handleDLResult(parsedResult);
    } catch (ex) {
      processedResult = [
        { description: "Error", value: ex.message || "parse failed." },
        {
          description: "Original text",
          value: barcodeResultItem.text,
        },
      ];
    }

    try {
      onDriverLicenseResult(processedResult);
    } catch (ex) {
      console.error(ex);
    }
    generateResultList(processedResult);
    barcodeText.textContent = barcodeResultItem.text.replace(/\n/g, "");
    parsedResultView.style.display = '';
  }

  function handleDLResult(parsedResult) {
    const oriParseInfo = [];
    const resultInfo = JSON.parse(parsedResult.jsonString);
    if (parsedResult.codeType === "AAMVA_DL_ID") {
      for (let info of resultInfo.ResultInfo) {
        if (info.FieldName !== "commonSubfile") continue;
        if (info.ChildFields) {
          wrapResultObject(info.ChildFields);
        }
      }
    } else if (parsedResult.codeType === "AAMVA_DL_ID_WITH_MAG_STRIPE") {
      for (let info of resultInfo.ResultInfo) {
        if (info.FieldName.includes("track")) {
          if (info.ChildFields) {
            wrapResultObject(info.ChildFields);
          }
        }
      }
    } else if (parsedResult.codeType === "SOUTH_AFRICA_DL") {
      for (let info of resultInfo.ResultInfo) {
        if (info.ChildFields) {
          wrapResultObject(info.ChildFields);
        } else {
          if (info.Value) {
            oriParseInfo.push({
              description: info.FieldName,
              value: info.Value,
            });
          }
        }
      }
    }

    function wrapResultObject(childFields) {
      for (let childField of childFields) {
        for (let field of childField) {
          if (!["dataElementSeparator", "segmentTerminator", "subfile", "subfileType"].includes(field.FieldName)) {
            if (field.Value) {
              oriParseInfo.push({
                description: field.FieldName,
                value: field.Value,
              });
            }
          }
          if (field.ChildFields) {
            wrapResultObject(field.ChildFields);
          }
        }
      }
    }
    return oriParseInfo;
  }

  function generateResultList(processedResult) {
    const resultList = processedResult.map((item) => {
      const resultItem = document.createElement("li");
      resultItem.className = "parsed-result-item";

      const description = document.createElement("strong");
      description.textContent = `${item.description}: `;
      const value = document.createElement("span");
      value.textContent = item.value ?? "";

      resultItem.append(description, value);
      return resultItem;
    });
    parsedResultList.replaceChildren(...resultList);
  }

  startBtn.addEventListener("click", () => {
    loading.style.display = "block";
    startIcon.style.display = "none";
    start();
  })

  backToScan.addEventListener("click", () => {
    parsedResultView.style.display = "none";
    isHandlingResult = false;
    start();
  })

  uploadImageBtn.addEventListener("click", () => {
    uploadImageInput.click();
  });

  uploadImageInput.addEventListener("change", async () => {
    const file = uploadImageInput.files?.[0];
    uploadImageInput.value = "";
    if (!file) return;

    uploadImageBtn.disabled = true;
    let shouldResumeScanning = false;
    try {
      await pInit;
      if (isHandlingResult) return;

      shouldResumeScanning = cvRouter.isCapturing;
      if (shouldResumeScanning) {
        cvRouter.stopCapturing();
      }

      const captureResult = await cvRouter.capture(file, "ReadDriversLicense");
      const barcodeResultItems = captureResult.decodedBarcodesResult?.barcodeResultItems ?? [];
      if (barcodeResultItems.length === 0) {
        notify("No barcode found in this image. Please try another one.");
        return;
      }

      shouldResumeScanning = false;
      await showResult(barcodeResultItems[0]);
    } catch (ex) {
      console.error(ex);
      notify(ex.message || "Failed to read the image.");
    } finally {
      uploadImageBtn.disabled = false;
      if (shouldResumeScanning && !isHandlingResult) {
        try {
          await cvRouter.startCapturing("ReadDriversLicense");
        } catch (ex) {
          console.error(ex);
        }
      }
    }
  });

  function notify(message) {
    if (typeof camera.funcShowToast === "function") {
      camera.funcShowToast(message);
    } else {
      console.warn(message);
    }
  }
})();
